import{c as t,Q as o,j as a,m as r}from"./chunks/framework.g_l1frA7.js";const p=JSON.parse('{"title":"Scenarios","description":"","frontmatter":{},"headers":[],"relativePath":"copilot/scenarios.md","filePath":"copilot/scenarios.md","lastUpdated":null}'),i={name:"copilot/scenarios.md"};function n(s,e,l,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="scenarios" tabindex="-1">Scenarios <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;Scenarios&quot;">​</a></h1><p>Scenarios answer “what if?” with math, not vibes.</p><h2 id="natural-language-→-structured-tools" tabindex="-1">Natural language → structured tools <a class="header-anchor" href="#natural-language-→-structured-tools" aria-label="Permalink to &quot;Natural language → structured tools&quot;">​</a></h2><p>On <strong>Copilot</strong> or <strong>Scenarios</strong>, type:</p><blockquote><p>“What if I cut dining by $200/month for a year and put it toward the emergency fund?”</p></blockquote><p>The Copilot maps_free text to deterministic tool calls (<code>adjust_recurring</code>, <code>set_monthly_contribution</code>, <code>set_expense</code>, …). Those tools run in <code>finsight-core::forecast</code>, which projects balances forward from your current ledger plus recurring assumptions.</p><p>Results return as a dated projection with a narrative — the Copilot explains the trade-off, the tools provide the numbers.</p><h2 id="saving-and-comparing" tabindex="-1">Saving and comparing <a class="header-anchor" href="#saving-and-comparing" aria-label="Permalink to &quot;Saving and comparing&quot;">​</a></h2><ul><li><strong>Save</strong> a scenario to revisit after new imports — it refreshes against the latest ledger.</li><li><strong>Compare</strong> two saved scenarios to see which ends richer in 12 months.</li></ul><h2 id="what-the-copilot-will-not-do" tabindex="-1">What the Copilot will not do <a class="header-anchor" href="#what-the-copilot-will-not-do" aria-label="Permalink to &quot;What the Copilot will not do&quot;">​</a></h2><ul><li>Predict market returns or invent exchange rates.</li><li>Summarize a single-currency subtotal as your whole position when unconverted holdings exist — the <code>CurrencyContext</code> block forbids it.</li><li>Auto-save a scenario you have not approved.</li></ul><p>See also: <a href="/FinSight/guide/scenarios">Guide → Scenarios</a>, <a href="/FinSight/developers/crates">Forecast in code</a>.</p>',12)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
